SELECT 
    (SELECT AVG("ball_control_score") FROM "players" WHERE "player_name" = 'Abdou Diallo') -
    (SELECT AVG("ball_control_score") FROM "players" WHERE "player_name" = 'Aaron Appindangoye') AS "difference";

SELECT ("overall_rating" - (SELECT "overall_rating" FROM "players" WHERE "player_name" = 'Paulin Puel')) * 100.0 / (SELECT "overall_rating" FROM "players" WHERE "player_name" = 'Paulin Puel') AS percentage_difference
FROM "players"
WHERE "player_name" = 'Ariel Borysiuk';
